fn runtime_role(acting_role: &str) -> &'static str {
    match acting_role {
        "planner" | "implementer" | "tester" | "evidence" | "executor" => "executor",
        "reviewer" | "independent_reviewer" => "reviewer",
        "adjudicator" => "adjudicator",
        _ => "",
    }
}

